using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using System.IO;

[InitializeOnLoad]
public static class BootPlayModeInterceptor
{
    private const string BootSceneName = "_Boot";
    private const string ResourcesFolder = "Assets/Resources";
    private const string ResourceAssetPath = "Assets/Resources/BootSceneTarget.asset";

    static BootPlayModeInterceptor()
    {
        EditorApplication.playModeStateChanged += OnPlayModeStateChanged;
    }

    private static void OnPlayModeStateChanged(PlayModeStateChange state)
    {
        if (state == PlayModeStateChange.ExitingEditMode)
        {
            // Before entering Play, find the _Boot scene asset
            var bootGuid = AssetDatabase.FindAssets("t:Scene " + BootSceneName);
            if (bootGuid == null || bootGuid.Length == 0)
            {
                if (!EditorUtility.DisplayDialog("_Boot scene not found", "No scene named '_Boot' was found in the project. Cancel Play or create an _Boot scene.", "Cancel Play", "Continue Anyway"))
                {
                    // Cancel play: abort by returning to Edit mode
                    EditorApplication.isPlaying = false;
                    return;
                }
                else
                {
                    // Continue without setting a start scene
                    return;
                }
            }

            // Use the first match
            var bootPath = AssetDatabase.GUIDToAssetPath(bootGuid[0]);
            var bootSceneAsset = AssetDatabase.LoadAssetAtPath<SceneAsset>(bootPath);
            if (bootSceneAsset == null)
            {
                Debug.LogError("BootPlayModeInterceptor: Failed to load SceneAsset for _Boot.");
                return;
            }

            // Save the currently active scene path into a ScriptableObject under Resources
            var activeScene = UnityEditor.SceneManagement.EditorSceneManager.GetActiveScene();
            var targetPath = activeScene.path; // e.g. Assets/Scenes/Level1.unity
            var targetName = Path.GetFileNameWithoutExtension(targetPath);

            // Ensure Resources folder exists
            if (!AssetDatabase.IsValidFolder(ResourcesFolder))
            {
                AssetDatabase.CreateFolder("Assets", "Resources");
            }

            BootSceneTarget asset = AssetDatabase.LoadAssetAtPath<BootSceneTarget>(ResourceAssetPath);
            if (asset == null)
            {
                asset = ScriptableObject.CreateInstance<BootSceneTarget>();
                AssetDatabase.CreateAsset(asset, ResourceAssetPath);
            }

            asset.TargetScenePath = targetPath;
            asset.TargetSceneName = targetName;
            EditorUtility.SetDirty(asset);
            AssetDatabase.SaveAssets();

            // Set the playModeStartScene to _Boot
            UnityEditor.SceneManagement.EditorSceneManager.playModeStartScene = bootSceneAsset;
            Debug.Log($"BootPlayModeInterceptor: Starting Play from '{bootPath}', saved target '{targetPath}'.");
        }

        if (state == PlayModeStateChange.EnteredEditMode)
        {
            // Clear the custom start scene after exiting Play
            UnityEditor.SceneManagement.EditorSceneManager.playModeStartScene = null;
            // Optionally, remove or clear the resources asset
            var asset = AssetDatabase.LoadAssetAtPath<BootSceneTarget>(ResourceAssetPath);
            if (asset != null)
            {
                asset.TargetScenePath = string.Empty;
                asset.TargetSceneName = string.Empty;
                EditorUtility.SetDirty(asset);
                AssetDatabase.SaveAssets();
            }
        }
    }
}

using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using System.IO;

[InitializeOnLoad]
public static class BootPlayModeInterceptor
{
    private const string BootSceneName = "_Boot";
    private const string ResourcesFolder = "Assets/Resources";
    private const string ResourceAssetPath = "Assets/Resources/BootSceneTarget.asset";

    static BootPlayModeInterceptor()
    {
        EditorApplication.playModeStateChanged += OnPlayModeStateChanged;
    }

    private static void OnPlayModeStateChanged(PlayModeStateChange state)
    {
        if (state == PlayModeStateChange.ExitingEditMode)
        {
            // Before entering Play, locate the _Boot scene asset by filename to be robust
            var guids = AssetDatabase.FindAssets("t:Scene");
            string bootPath = null;
            foreach (var g in guids)
            {
                var p = AssetDatabase.GUIDToAssetPath(g);
                var filename = System.IO.Path.GetFileNameWithoutExtension(p);
                if (string.Equals(filename, BootSceneName, System.StringComparison.OrdinalIgnoreCase))
                {
                    bootPath = p;
                    break;
                }
            }

            if (string.IsNullOrEmpty(bootPath))
            {
                if (!EditorUtility.DisplayDialog("_Boot scene not found", "No scene named '_Boot' was found in the project. Cancel Play or create an _Boot scene.", "Cancel Play", "Continue Anyway"))
                {
                    // Cancel play: abort by returning to Edit mode
                    EditorApplication.isPlaying = false;
                    return;
                }
                else
                {
                    // Continue without setting a start scene
                    return;
                }
            }

            var bootSceneAsset = AssetDatabase.LoadAssetAtPath<SceneAsset>(bootPath);
            if (bootSceneAsset == null)
            {
                Debug.LogError("BootPlayModeInterceptor: Failed to load SceneAsset for _Boot.");
                return;
            }

            // Save the currently active scene path into a ScriptableObject under Resources
            var activeScene = UnityEditor.SceneManagement.EditorSceneManager.GetActiveScene();
            var targetPath = activeScene.path; // e.g. Assets/Scenes/Level1.unity
            var targetName = Path.GetFileNameWithoutExtension(targetPath);

            // If the user started Play while already on the _Boot scene, override the target to Splash
            if (string.Equals(targetName, BootSceneName, System.StringComparison.OrdinalIgnoreCase))
            {
                targetPath = string.Empty;
                targetName = "Splash";
            }

            // Ensure Resources folder exists
            if (!AssetDatabase.IsValidFolder(ResourcesFolder))
            {
                AssetDatabase.CreateFolder("Assets", "Resources");
            }

            BootSceneTarget asset = AssetDatabase.LoadAssetAtPath<BootSceneTarget>(ResourceAssetPath);
            if (asset == null)
            {
                asset = ScriptableObject.CreateInstance<BootSceneTarget>();
                AssetDatabase.CreateAsset(asset, ResourceAssetPath);
            }

            asset.TargetScenePath = targetPath;
            asset.TargetSceneName = targetName;
            EditorUtility.SetDirty(asset);
            AssetDatabase.SaveAssets();

            // Set the playModeStartScene to _Boot
            UnityEditor.SceneManagement.EditorSceneManager.playModeStartScene = bootSceneAsset;
            Debug.Log($"BootPlayModeInterceptor: Starting Play from '{bootPath}', saved target '{targetName}' (path '{targetPath}').");
        }

        if (state == PlayModeStateChange.EnteredEditMode)
        {
            // Clear the custom start scene after exiting Play
            UnityEditor.SceneManagement.EditorSceneManager.playModeStartScene = null;
            // Optionally, remove or clear the resources asset
            var asset = AssetDatabase.LoadAssetAtPath<BootSceneTarget>(ResourceAssetPath);
            if (asset != null)
            {
                asset.TargetScenePath = string.Empty;
                asset.TargetSceneName = string.Empty;
                EditorUtility.SetDirty(asset);
                AssetDatabase.SaveAssets();
            }
        }
    }
}

using UnityEditor;
using UnityEngine;

[InitializeOnLoad]
internal static class EnsureBootSceneTarget
{
    private const string ResourceAssetPath = "Assets/Resources/BootSceneTarget.asset";

    static EnsureBootSceneTarget()
    {
        EditorApplication.delayCall += EnsureAssetExists;
    }

    private static void EnsureAssetExists()
    {
        var asset = AssetDatabase.LoadAssetAtPath<BootSceneTarget>(ResourceAssetPath);
        if (asset == null)
        {
            var instance = ScriptableObject.CreateInstance<BootSceneTarget>();
            instance.TargetSceneName = "Splash";
            // create Resources folder if missing
            if (!AssetDatabase.IsValidFolder("Assets/Resources"))
                AssetDatabase.CreateFolder("Assets", "Resources");
            AssetDatabase.CreateAsset(instance, ResourceAssetPath);
            AssetDatabase.SaveAssets();
            Debug.Log("EnsureBootSceneTarget: Created Resources/BootSceneTarget.asset with TargetSceneName='Splash'.");
        }
        // Also ensure the _Boot scene contains a BootSceneLoader GameObject so the redirect will run in Play.
        EnsureBootSceneHasLoader();
    }

    private static void EnsureBootSceneHasLoader()
    {
        // Find boot scene path
        var guids = AssetDatabase.FindAssets("t:Scene");
        string bootPath = null;
        foreach (var g in guids)
        {
            var p = AssetDatabase.GUIDToAssetPath(g);
            var filename = System.IO.Path.GetFileNameWithoutExtension(p);
            if (string.Equals(filename, "_Boot", System.StringComparison.OrdinalIgnoreCase))
            {
                bootPath = p;
                break;
            }
        }
        if (string.IsNullOrEmpty(bootPath))
        {
            Debug.LogWarning("EnsureBootSceneTarget: _Boot scene not found in project.");
            return;
        }

        // Remember current scene
        var active = UnityEditor.SceneManagement.EditorSceneManager.GetActiveScene();

        // Open boot scene additively to modify
        var scene = UnityEditor.SceneManagement.EditorSceneManager.OpenScene(bootPath, UnityEditor.SceneManagement.OpenSceneMode.Additive);
        if (!scene.IsValid())
        {
            Debug.LogWarning($"EnsureBootSceneTarget: failed to open _Boot scene at '{bootPath}'.");
            return;
        }

        bool changed = false;
        // Check for existing BootSceneLoader
        var rootGOs = scene.GetRootGameObjects();
        bool hasLoader = false;
        foreach (var go in rootGOs)
        {
            if (go.GetComponent<BootSceneLoader>() != null)
            {
                hasLoader = true;
                break;
            }
        }

        if (!hasLoader)
        {
            var go = new GameObject("BootRunner");
            go.AddComponent<BootSceneLoader>();
            UnityEditor.SceneManagement.EditorSceneManager.MoveGameObjectToScene(go, scene);
            changed = true;
            Debug.Log("EnsureBootSceneTarget: Added BootSceneLoader to _Boot scene.");
        }

        // Optionally ensure there's a GameManagerCore/GameManager present
        bool hasGM = false;
        rootGOs = scene.GetRootGameObjects();
        foreach (var go in rootGOs)
        {
            if (go.GetComponent<GameManagerCore>() != null || go.GetComponent("GameManager") != null)
            {
                hasGM = true;
                break;
            }
        }
        if (!hasGM)
        {
            var go = new GameObject("GameManager");
            go.AddComponent<GameManagerCore>();
            UnityEditor.SceneManagement.EditorSceneManager.MoveGameObjectToScene(go, scene);
            changed = true;
            Debug.Log("EnsureBootSceneTarget: Added GameManagerCore to _Boot scene.");
        }

        if (changed)
        {
            UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(scene);
            UnityEditor.SceneManagement.EditorSceneManager.SaveScene(scene);
            Debug.Log("EnsureBootSceneTarget: _Boot scene updated and saved.");
        }

        // Close the additive scene and restore active
        UnityEditor.SceneManagement.EditorSceneManager.CloseScene(scene, true);
        UnityEditor.SceneManagement.EditorSceneManager.OpenScene(active.path, UnityEditor.SceneManagement.OpenSceneMode.Single);
    }
}

using UnityEngine;

[CreateAssetMenu(menuName = "Bootstrap/BootSceneTarget")]
public class BootSceneTarget : ScriptableObject
{
    // Full asset path (e.g. "Assets/Scenes/Level1.unity"). Written by the editor before entering Play.
    public string TargetScenePath;

    // Scene name (filename without extension). Used at runtime to load the scene by name.
    public string TargetSceneName;
}

using UnityEngine;

[CreateAssetMenu(menuName = "Bootstrap/BootSceneTarget")]
public class BootSceneTarget : ScriptableObject
{
    // Full asset path (e.g. "Assets/Scenes/Level1.unity"). Written by the editor before entering Play.
    public string TargetScenePath;

    // Scene name (filename without extension). Used at runtime to load the scene by name.
    [Tooltip("Scene name (filename without extension) that the Boot scene will redirect to. Defaults to 'Splash'.")]
    public string TargetSceneName = "Splash";
}

using System.Collections;
using UnityEngine;
using UnityEngine.SceneManagement;

#if ENABLE_INPUT_SYSTEM
using UnityEngine.InputSystem;
using UnityEngine.InputSystem.Users;
#endif

/// <summary>
/// GameManagerCore: core implementation of a GameManager singleton. If a user-defined
/// GameManager.cs exists, it will be a separate class; this file provides the behavior
/// requested in the task under a different name to avoid collisions.
/// Place this component on a GameObject named 'GameManager' in the _Boot scene.
/// </summary>
public class GameManagerCore : MonoBehaviour
{
    public enum GameState { Iniciando, MenuPrincipal, Gameplay }

    private static GameManagerCore _instance;
    public static GameManagerCore Instance => _instance;

    [Header("Optional PlayerInput holder (assign GameObject with PlayerInput)")]
    public MonoBehaviour playerInputHolder;

    private GameState _state = GameState.Iniciando;

    private void Awake()
    {
        if (_instance != null && _instance != this)
        {
            Destroy(gameObject);
            return;
        }
        _instance = this;
        DontDestroyOnLoad(gameObject);
        Debug.Log("GameManagerCore: Awake - instance created. State=" + _state);
    }

    private void Start()
    {
        SetState(GameState.Iniciando);
#if ENABLE_INPUT_SYSTEM
        AllocateInputToPlayer();
#else
        Debug.Log("GameManagerCore: Input System not enabled or unavailable.");
#endif
    }

    private void SetState(GameState newState)
    {
        if (_state == newState) return;
        Debug.Log($"GameManagerCore: State change {_state} -> {newState}");
        _state = newState;
    }

    public void ForceSceneChange(string sceneName)
    {
        if (string.IsNullOrEmpty(sceneName))
        {
            Debug.LogWarning("GameManagerCore.ForceSceneChange: empty sceneName");
            return;
        }
        StartCoroutine(DoForceSceneChange(sceneName));
    }

    private IEnumerator DoForceSceneChange(string sceneName)
    {
        var op = SceneManager.LoadSceneAsync(sceneName, LoadSceneMode.Single);
        if (op == null)
        {
            Debug.LogError($"GameManagerCore: Failed to start loading scene '{sceneName}'. Ensure it's in Build Settings.");
            yield break;
        }
        while (!op.isDone) yield return null;

        if (sceneName.ToLowerInvariant().Contains("menu")) SetState(GameState.MenuPrincipal);
        else if (sceneName.ToLowerInvariant().Contains("sample") || sceneName.ToLowerInvariant().Contains("game")) SetState(GameState.Gameplay);
        else Debug.Log($"GameManagerCore: Scene '{sceneName}' loaded. State remains {_state}.");
    }

    public void RequestSceneChange(string sceneName) => ForceSceneChange(sceneName);

    public void StartBootLoad(string targetSceneName)
    {
        if (string.IsNullOrEmpty(targetSceneName)) { Debug.LogError("GameManagerCore.StartBootLoad: empty target"); return; }
        StartCoroutine(BootLoadCoroutine(targetSceneName));
    }

    private IEnumerator BootLoadCoroutine(string targetSceneName)
    {
        Debug.Log($"GameManagerCore: Boot loading target '{targetSceneName}'");
        var loadOp = SceneManager.LoadSceneAsync(targetSceneName, LoadSceneMode.Additive);
        if (loadOp == null) { Debug.LogError($"GameManagerCore: Failed to start loading scene '{targetSceneName}'."); yield break; }
        while (!loadOp.isDone) yield return null;

        var loadedScene = SceneManager.GetSceneByName(targetSceneName);
        if (loadedScene.IsValid()) SceneManager.SetActiveScene(loadedScene);

        for (int i = 0; i < SceneManager.sceneCount; ++i)
        {
            var sc = SceneManager.GetSceneAt(i);
            if (!sc.IsValid() || !sc.isLoaded) continue;
            if (string.Equals(sc.name, targetSceneName, System.StringComparison.OrdinalIgnoreCase)) continue;

            string filename = System.IO.Path.GetFileNameWithoutExtension(sc.path);
            bool isBootName = string.Equals(sc.name, "_Boot", System.StringComparison.OrdinalIgnoreCase) || string.Equals(filename, "_Boot", System.StringComparison.OrdinalIgnoreCase);
            bool containsGM = SceneContainsGameManager(sc);
            if (isBootName || containsGM)
            {
                Debug.Log($"GameManagerCore: Unloading boot scene '{sc.name}' (containsGM={containsGM})");
                SceneManager.UnloadSceneAsync(sc);
            }
        }

        if (targetSceneName.ToLowerInvariant().Contains("menu")) SetState(GameState.MenuPrincipal);
        else SetState(GameState.Gameplay);
    }

    private bool SceneContainsGameManager(Scene sc)
    {
        if (!sc.IsValid() || !sc.isLoaded) return false;
        try
        {
            var roots = sc.GetRootGameObjects();
            foreach (var go in roots)
            {
                if (go == null) continue;
                if (go.GetComponent<GameManagerCore>() != null) return true;
                if (go.GetComponentInChildren<GameManagerCore>(true) != null) return true;
            }
        }
        catch { }
        return false;
    }

#if ENABLE_INPUT_SYSTEM
    private void AllocateInputToPlayer()
    {
        if (playerInputHolder == null) { Debug.Log("GameManagerCore: No playerInputHolder assigned."); return; }
        var pi = playerInputHolder.GetComponent<UnityEngine.InputSystem.PlayerInput>();
        if (pi == null) { Debug.Log("GameManagerCore: playerInputHolder has no PlayerInput."); return; }
        var devices = InputSystem.devices;
        if (devices.Count == 0) { Debug.Log("GameManagerCore: No devices available."); return; }
        var device = devices[0];
        try { InputUser.PerformPairingWithDevice(device, pi.user); Debug.Log($"GameManagerCore: Paired '{device.displayName}' to PlayerInput."); }
        catch (System.Exception ex) { Debug.LogWarning($"GameManagerCore: Failed to pair device: {ex}"); }
    }
#endif
}

using UnityEngine;

/// <summary>
/// Simple UI controller for the main menu. Attach to a GameObject in the MenuPrincipal scene
/// and wire the OnStartClicked and OnQuitClicked methods to the respective UI buttons.
/// </summary>
public class MenuUiController : MonoBehaviour
{
    public void OnStartClicked()
    {
        if (GameManager.Instance != null)
        {
            GameManager.Instance.RequestSceneChange("SampleScene");
        }
        else
        {
            Debug.LogWarning("MenuUiController: GameManager not found. Loading SampleScene directly.");
            UnityEngine.SceneManagement.SceneManager.LoadScene("SampleScene");
        }
    }

    public void OnQuitClicked()
    {
        Debug.Log("MenuUiController: Quit requested.");
        Application.Quit();
    }
}

using System.Collections;
using UnityEngine;

/// <summary>
/// Controls the Splash scene. Shows the splash image for a fixed duration and then
/// requests a transition to the MenuPrincipal scene via GameManager.
/// </summary>
public class SplashController : MonoBehaviour
{
    [Tooltip("Tempo em segundos que a splash ficará visível")]
    public float displaySeconds = 2f;

    private IEnumerator Start()
    {
        // Wait for the UI to render
        yield return null;

        // Wait the configured duration
        yield return new WaitForSeconds(displaySeconds);

        // After the splash, force the transition to MenuPrincipal
        if (GameManager.Instance != null)
        {
            GameManager.Instance.ForceSceneChange("MenuPrincipal");
        }
        else
        {
            Debug.LogWarning("SplashController: GameManager not found. Attempting direct scene load.");
            UnityEngine.SceneManagement.SceneManager.LoadScene("MenuPrincipal");
        }
    }
}
